import { clockMinutes, durationMinutes, durationLabel, validDate, isBand } from './plan-model.js';
const $=id=>document.getElementById(id);
let songs=[], user=null, cloud=null, records=[], unsubscribe=null, expectedUpdatedAt=null, dirty=false, saving=false, fromCache=true, timer;
const blank=()=>({ids:[],event:'',notes:'',date:'',startTime:'',endTime:'',cloudId:null,ownerUid:null});
let plan=blank(), storageOK=true;
function draftKey(){return user?'n64-draft-'+user.uid:'n64-plan-v1';}
function restoreDraft(){plan=blank();try{const p=JSON.parse(localStorage.getItem(draftKey()));if(p&&Array.isArray(p.ids)){plan={...plan,...p,ids:[...new Set(p.ids.filter(Number.isInteger))],event:typeof p.event==='string'?p.event.slice(0,120):'',notes:typeof p.notes==='string'?p.notes.slice(0,4000):''};}}catch(e){storageOK=false;}expectedUpdatedAt=null;dirty=true;}
restoreDraft();
const readOnly=()=>!!plan.ownerUid&&plan.ownerUid!==user?.uid;
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const time=s=>s==null?'—':`${Math.floor(s/60)}:${String(s%60).padStart(2,'0')}`;
function toast(msg){$('toast').textContent=msg;$('toast').style.display='block';clearTimeout(timer);timer=setTimeout(()=>$('toast').style.display='none',2200);}
function save(){if(!readOnly()){try{localStorage.setItem(draftKey(),JSON.stringify(plan));storageOK=true;}catch(e){storageOK=false;}}$('saveStatus').textContent=storageOK?'Draft kept on this device. Save for Nickel 64 to share it with Dave and Rob.':'Device saving is unavailable. Save for Nickel 64 or download a copy before closing.';renderCloudState();}
function schedule(){const start=clockMinutes(plan.startTime),end=clockMinutes(plan.endTime),minutes=durationMinutes(start,end);$('eventDuration').textContent=minutes==null?'Add distinct start and end times to calculate event duration.':`Event duration: ${durationLabel(minutes)}${end<start?' · ends the next day':''}`;}
function renderCloudState(){const ro=readOnly();['event','date','startTime','endTime','notes'].forEach(id=>$(id).disabled=ro||saving);$('newPlan').disabled=saving;$('clear').disabled=ro||saving||!plan.ids.length;$('cloudSave').disabled=saving||ro;$('cloudSave').textContent=saving?'Saving…':plan.cloudId?'Save changes for Nickel 64':'Save for Nickel 64';if(ro)$('cloudStatus').textContent='Viewing a client’s saved setlist. Only its creator can edit it.';else if(!cloud)$('cloudStatus').textContent='Connecting to shared setlists…';else if(!user)$('cloudStatus').textContent='Sign in to save a setlist for Dave and Rob.';else if(!user.emailVerified)$('cloudStatus').textContent='Verify your email, then check verification to save for Dave and Rob.';else $('cloudStatus').textContent=dirty?'Unsaved changes. Save to make them available to Dave and Rob.':plan.cloudId?'Saved for Nickel 64. Dave and Rob can view this setlist.':'Ready to save for Dave and Rob.';}
function library(){const q=$('search').value.trim().toLowerCase(),d=$('decade').value,sort=$('sort').value;const list=songs.filter(s=>(s.title+' '+s.artist).toLowerCase().includes(q)&&(d==='all'||s.year&&Math.floor(s.year/10)*10===Number(d))).sort((a,b)=>sort==='year'?(b.year||0)-(a.year||0):sort==='bpm'?(a.bpm??Infinity)-(b.bpm??Infinity):String(a[sort]).localeCompare(String(b[sort])));$('count').textContent=`${list.length} songs`;$('songs').innerHTML=list.length?list.map(s=>`<div class="song"><div><div class="title">${esc(s.title)}</div><div class="artist">${esc(s.artist)}</div></div><span class="meta year">${s.year||'—'}</span><span class="meta">${s.bpm||'—'}</span><span class="meta">${time(s.seconds)}</span><button data-add="${s.id}" ${readOnly()||saving?'disabled':''} class="${plan.ids.includes(s.id)?'added':''}" aria-label="${plan.ids.includes(s.id)?'Remove':'Add'} ${esc(s.title)} ${plan.ids.includes(s.id)?'from':'to'} setlist" aria-pressed="${plan.ids.includes(s.id)}">${plan.ids.includes(s.id)?'✓':'+'}</button></div>`).join(''):'<div class="no-results">No songs found. Try another song, artist or decade.</div>';}
function selected(){const list=plan.ids.map(id=>songs.find(s=>s.id===id)).filter(Boolean),secs=list.reduce((sum,s)=>sum+(s.seconds||0),0),missing=list.filter(s=>s.seconds==null).length;$('selectedCount').textContent=list.length;$('minutes').textContent=`${Math.round(secs/60)} min`;$('unknown').textContent=missing?`${missing} song${missing===1?' has':'s have'} no duration; the total excludes ${missing===1?'it':'them'}.`:'';$('empty').hidden=!!list.length;$('setlist').innerHTML=list.map((s,i)=>`<li><span class="number">${String(i+1).padStart(2,'0')}</span><div class="selected-song">${esc(s.title)}<small>${esc(s.artist)} · ${time(s.seconds)}</small></div><div class="actions"><button data-move="${s.id}" data-dir="-1" aria-label="Move ${esc(s.title)} up" ${readOnly()||i===0?'disabled':''}>↑</button><button data-move="${s.id}" data-dir="1" aria-label="Move ${esc(s.title)} down" ${readOnly()||i===list.length-1?'disabled':''}>↓</button><button ${readOnly()||saving?'disabled':''} data-remove="${s.id}" aria-label="Remove ${esc(s.title)}">×</button></div></li>`).join('');$('export').disabled=!list.length;$('print').disabled=!list.length;$('clear').disabled=!list.length;}
function update(changed=true){if(changed)dirty=true;library();selected();schedule();save();}function toggle(id){if(readOnly()||saving)throw new Error('This setlist cannot be edited right now');if(!songs.some(s=>s.id===id))throw new Error('Unknown song');if(plan.ids.includes(id))plan.ids=plan.ids.filter(x=>x!==id);else plan.ids.push(id);update();}
$('songs').addEventListener('click',e=>{const b=e.target.closest('[data-add]');if(b)toggle(Number(b.dataset.add));});$('setlist').addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.remove!==undefined)toggle(Number(b.dataset.remove));else if(b.dataset.move!==undefined){const i=plan.ids.indexOf(Number(b.dataset.move)),j=i+Number(b.dataset.dir);if(!readOnly()&&!saving&&i>=0&&j>=0&&j<plan.ids.length){[plan.ids[i],plan.ids[j]]=[plan.ids[j],plan.ids[i]];update();}}});['search','decade','sort'].forEach(id=>$(id).addEventListener('input',library));['event','notes','date','startTime','endTime'].forEach(id=>$(id).addEventListener('input',()=>{if(readOnly())return;plan[id]=$(id).value;dirty=true;schedule();save();}));$('clear').onclick=()=>{if(confirm('Clear all selected songs? Your event name and notes will stay.')){plan.ids=[];update();}};$('print').onclick=()=>window.print();$('export').onclick=()=>{const list=plan.ids.map(id=>songs.find(s=>s.id===id)),secs=list.reduce((n,s)=>n+(s.seconds||0),0);const txt=`NICKEL 64 SETLIST\n${plan.event||'Event music plan'}\nDate: ${plan.date||'Not set'}\nTime: ${plan.startTime||'—'}–${plan.endTime||'—'}${clockMinutes(plan.endTime)<clockMinutes(plan.startTime)?' (next day)':''}\nEvent duration: ${durationLabel(durationMinutes(clockMinutes(plan.startTime),clockMinutes(plan.endTime)))}\n\n${list.map((s,i)=>`${i+1}. ${s.title} — ${s.artist} (${time(s.seconds)})`).join('\n')}\n\n${list.length} songs · ${Math.round(secs/60)} minutes of known durations\nTimes are estimates; missing durations are excluded.\n\nNOTES\n${plan.notes||'None'}\n\nConfirm songs and arrangements with N64.\n`;const url=URL.createObjectURL(new Blob([txt],{type:'text/plain;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download='N64-setlist.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Setlist downloaded. Ready to send to N64.');};
async function init(){try{const r=await fetch('songs.json');if(!r.ok)throw new Error('Library unavailable');songs=await r.json();plan.ids=plan.ids.filter(id=>songs.some(s=>s.id===id));$('total').textContent=songs.length;const decades=[...new Set(songs.filter(s=>s.year).map(s=>Math.floor(s.year/10)*10))].sort((a,b)=>b-a);$('decade').innerHTML+=decades.map(d=>`<option value="${d}">${d}s</option>`).join('');fillPlan();update(false);registerTools();connectCloud();}catch(e){$('songs').innerHTML='<p>Unable to load the song library. Please reload the page.</p>';return;}}

function registerTools(){if(!document.modelContext?.registerTool)return;try{Promise.resolve(document.modelContext.registerTool({name:'search_n64_songs',description:'Find songs in the N64 library.',inputSchema:{type:'object',properties:{query:{type:'string'}},required:['query'],additionalProperties:false},annotations:{readOnlyHint:true},execute(input){if(!input||typeof input.query!=='string')throw new Error('query must be text');const q=input.query.toLowerCase();return songs.filter(s=>(s.title+' '+s.artist).toLowerCase().includes(q));}})).catch(()=>{});Promise.resolve(document.modelContext.registerTool({name:'add_songs_to_setlist',description:'Add library songs to the current device setlist.',inputSchema:{type:'object',properties:{songIds:{type:'array',items:{type:'integer'}}},required:['songIds'],additionalProperties:false},annotations:{readOnlyHint:false},execute(input){if(!input||!Array.isArray(input.songIds)||input.songIds.some(id=>!Number.isInteger(id)||!songs.some(s=>s.id===id)))throw new Error('Use valid song IDs');if(readOnly()||saving)throw new Error('This setlist cannot be edited right now');plan.ids=[...new Set([...plan.ids,...input.songIds])];update();return {songIds:plan.ids};}})).catch(()=>{});}catch(e){}}


function fillPlan(){['event','notes','date','startTime','endTime'].forEach(id=>$(id).value=plan[id]||'');}
function errorMessage(error){const messages={'auth/unauthorized-domain':'Sign-in is not enabled for this website yet. Please contact the app owner.','auth/operation-not-allowed':'This sign-in method is not enabled yet. Try another method.','auth/invalid-credential':'The email or password is incorrect.','auth/email-already-in-use':'This email already has an account. Sign in instead.','auth/weak-password':'Use a password with at least six characters.','auth/popup-blocked':'Allow the sign-in popup and try again.','auth/popup-closed-by-user':'Sign-in was cancelled.','auth/network-request-failed':'Connection failed. Please try again.','permission-denied':'Access was denied. Check your email verification or contact the app owner.','unavailable':'Shared setlists are temporarily unavailable. Your draft has been kept.'};return messages[error.code]||error.message||'Something went wrong. Please try again.';}
function openAuth(){if(!cloud){toast('Shared sign-in is unavailable. Please reload and try again.');return;}$('authStatus').textContent='';$('authDialog').showModal();}
$('signIn').onclick=openAuth;$('closeAuth').onclick=()=>$('authDialog').close();
$('signOut').onclick=async()=>{try{await cloud.logOut();}catch(e){toast(errorMessage(e));}};
async function authAction(action){try{$('authStatus').textContent='Signing in…';await action();$('authPassword').value='';$('authDialog').close();}catch(e){$('authStatus').textContent=errorMessage(e);}}
$('googleSignIn').onclick=()=>authAction(()=>cloud.googleSignIn());
$('authForm').onsubmit=e=>{e.preventDefault();authAction(()=>cloud.emailSignIn($('authEmail').value.trim(),$('authPassword').value));};
$('createAccount').onclick=()=>{if(!$('authForm').reportValidity())return;authAction(async()=>{await cloud.register($('authEmail').value.trim(),$('authPassword').value);toast('Verification email sent. Verify your email to save a setlist.');});};
$('resetPassword').onclick=async()=>{if(!$('authEmail').reportValidity())return;try{await cloud.resetPassword($('authEmail').value.trim());$('authStatus').textContent='If an account exists, a password reset email has been sent.';}catch(e){$('authStatus').textContent=errorMessage(e);}};
$('newPlan').onclick=()=>{if(dirty&&(plan.ids.length||plan.event)&&!confirm('Start a new setlist? Download or save the current draft first to keep it.'))return;plan=blank();expectedUpdatedAt=null;fillPlan();update();};
$('cloudSave').onclick=async()=>{
 if(saving)return;
 if(!cloud){toast('Shared saving is unavailable. Please reload and try again.');return;}
 if(!user){openAuth();return;}
 if(!user.emailVerified){try{await cloud.verifyEmail();toast('Verification email sent. Open the link, then check verification.');}catch(e){toast(errorMessage(e));}return;}
 if(readOnly())return;
 if(!plan.event.trim()||!validDate(plan.date)||durationMinutes(clockMinutes(plan.startTime),clockMinutes(plan.endTime))==null||!plan.ids.length){$('cloudStatus').textContent='Add an event name, date, distinct start and end times, and at least one song.';return;}
 saving=true;renderCloudState();library();selected();
 try{const submitted=JSON.parse(JSON.stringify(plan)),result=await cloud.savePlan(submitted,expectedUpdatedAt);plan.cloudId=result.id;plan.ownerUid=user.uid;expectedUpdatedAt=result.updatedAt;dirty=false;save();toast('Setlist saved for Dave and Rob.');}catch(e){$('cloudStatus').textContent=errorMessage(e);saving=false;library();selected();renderCloudState();$('cloudStatus').textContent=errorMessage(e);$('cloudSave').disabled=readOnly();$('cloudSave').textContent=plan.cloudId?'Save changes for Nickel 64':'Save for Nickel 64';return;}
 saving=false;library();selected();renderCloudState();
};
function fromRecord(r){return {...blank(),cloudId:r.id,ownerUid:r.ownerUid,event:r.event,notes:r.notes,date:r.eventDate.toDate().toISOString().slice(0,10),startTime:formatClock(r.startMinutes),endTime:formatClock(r.endMinutes),ids:r.songIds};}
function formatClock(m){return `${String(Math.floor(m/60)).padStart(2,'0')}:${String(m%60).padStart(2,'0')}`;}
function renderRecords(){
 const sorted=[...records].sort((a,b)=>a.eventDate.toMillis()-b.eventDate.toMillis()||a.startMinutes-b.startMinutes);
 $('savedPlans').innerHTML=sorted.map(r=>`<button class="saved-card" data-record="${esc(r.id)}"><strong>${esc(r.event)}</strong><span>${r.eventDate.toDate().toISOString().slice(0,10)} · ${formatClock(r.startMinutes)}–${formatClock(r.endMinutes)}${r.endMinutes<r.startMinutes?' (+1 day)':''}</span><span>${durationLabel(r.durationMinutes)} · ${r.songIds.length} songs</span></button>`).join('');
 $('savedStatus').textContent=fromCache?'Connecting… Saved records shown may be from this device’s cache.':sorted.length?'Saved setlists are available to Dave and Rob.':'No saved setlists yet.';
}
$('savedPlans').onclick=e=>{const b=e.target.closest('[data-record]');if(!b||saving)return;const r=records.find(r=>r.id===b.dataset.record);if(!r)return;if(dirty&&(plan.ids.length||plan.event)&&!confirm('Open the saved setlist? Unsaved changes to the current draft will be replaced.'))return;plan=fromRecord(r);expectedUpdatedAt=r.updatedAt;dirty=false;fillPlan();update(false);};
async function connectCloud(){try{cloud=await import('./cloud.js');cloud.watchUser(next=>{
 const previous=user;unsubscribe?.();unsubscribe=null;records=[];user=next;
 // A guest draft follows the first sign-in. Account-to-account switches use separate device drafts.
 if(previous?.uid!==next?.uid){if(!previous&&next&&!plan.cloudId){const guest=plan;restoreDraft();if(!plan.ids.length&&!plan.event)plan=guest;fillPlan();save();}else{restoreDraft();fillPlan();}expectedUpdatedAt=null;}
 $('accountLabel').textContent=user?.email||'';$('signIn').hidden=!!user;$('signOut').hidden=!user;$('savedPanel').hidden=!user;$('savedTitle').textContent=isBand(user)?'All setlists':'Your saved setlists';
 $('verificationActions').hidden=!user||user.emailVerified;
 if(user?.emailVerified){$('savedStatus').textContent='Loading saved setlists…';unsubscribe=cloud.watchPlans(user,(data,cached)=>{records=data;fromCache=cached;renderRecords();const current=data.find(r=>r.id===plan.cloudId);if(current&&!cached){if(!dirty||saving){expectedUpdatedAt=current.updatedAt;if(readOnly()){plan=fromRecord(current);fillPlan();update(false);}}}},error=>{$('savedStatus').textContent=errorMessage(error);});}
 else{$('savedPlans').innerHTML='';$('savedStatus').textContent=user?'Verify your email to view and save shared setlists.':'';}
 update(false);
 });}catch(e){$('cloudStatus').textContent='Shared saving is unavailable. You can still browse songs and download your draft.';cloud=null;$('signIn').disabled=true;}}
$('checkVerification').onclick=async()=>{try{const refreshed=await cloud.refreshUser();if(refreshed?.emailVerified){location.reload();}else toast('Email is not verified yet. Open the verification email first.');}catch(e){toast(errorMessage(e));}};
init();
